#ifndef MUOS_LOGO_H
#define MUOS_LOGO_H

/* Single source of truth for the version string. release.ps1 reads it from
 * this header, and every on-screen slogan uses the same value. */
#define MUOS_VERSION "v1.3"

#define LOGO_ROWS 5

/* Block letters "MuOS"; the drop shadow is generated by offsetting the
 * same glyphs two columns right and one row down. */
extern const char* const muos_logo[LOGO_ROWS];

/* Draw the extruded logo with the top-left glyph at cell (row, col). */
void logo_print_3d(int row, int col);

/* Boot / `logo` screen: clear, frame, 3D logo, taglines and hints.
 * Leaves the cursor on the prompt row. */
void logo_show(void);

#endif
